(function(){
  var B64C='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
  function b64e(b){var s='',i;for(i=0;i+2<b.length;i+=3){var n=(b[i]<<16)|(b[i+1]<<8)|b[i+2];
    s+=B64C[n>>18&63]+B64C[n>>12&63]+B64C[n>>6&63]+B64C[n&63];}
    var r=b.length-i;
    if(r===1){var n1=b[i]<<16;s+=B64C[n1>>18&63]+B64C[n1>>12&63]+'==';}
    else if(r===2){var n2=(b[i]<<16)|(b[i+1]<<8);s+=B64C[n2>>18&63]+B64C[n2>>12&63]+B64C[n2>>6&63]+'=';}
    return s;}
  function b64d(s){s=String(s).replace(/\s+/g,'').replace(/=+$/,'');
    if(/[^A-Za-z0-9+/]/.test(s)) return null;
    var o=[],i;
    for(i=0;i+3<s.length;i+=4){var n=(B64C.indexOf(s[i])<<18)|(B64C.indexOf(s[i+1])<<12)|(B64C.indexOf(s[i+2])<<6)|B64C.indexOf(s[i+3]);
      o.push(n>>16&255,n>>8&255,n&255);}
    var r=s.length-i;
    if(r===1) return null;
    if(r===2){var n3=(B64C.indexOf(s[i])<<18)|(B64C.indexOf(s[i+1])<<12);o.push(n3>>16&255);}
    else if(r===3){var n4=(B64C.indexOf(s[i])<<18)|(B64C.indexOf(s[i+1])<<12)|(B64C.indexOf(s[i+2])<<6);o.push(n4>>16&255,n4>>8&255);}
    return Uint8Array.from(o);}
  function utf8(s){
    var o=[],i,c;
    for(i=0;i<s.length;i++){
      c=s.charCodeAt(i);
      if(c<128)o.push(c);
      else if(c<2048){o.push(192|c>>6,128|c&63);}
      else if(c>=55296&&c<56320&&i+1<s.length){
        var c2=s.charCodeAt(i+1);i++;
        var cp=65536+((c-55296)<<10)+(c2-56320);
        o.push(240|cp>>18,128|cp>>12&63,128|cp>>6&63,128|cp&63);
      } else {o.push(224|c>>12,128|c>>6&63,128|c&63);}
    }
    return Uint8Array.from(o);}
  function fromUtf8(b){
    var s='',i=0;
    while(i<b.length){
      var c=b[i++];
      if(c<128)s+=String.fromCharCode(c);
      else if(c>191&&c<224)s+=String.fromCharCode((c&31)<<6|(b[i++]&63));
      else if(c>239){
        var cp=((c&7)<<18|(b[i++]&63)<<12|(b[i++]&63)<<6|(b[i++]&63))-65536;
        s+=String.fromCharCode(55296+(cp>>10),56320+(cp&1023));
      } else s+=String.fromCharCode((c&15)<<12|(b[i++]&63)<<6|(b[i++]&63));
    }
    return s;}

  var MIME={txt:'text/plain',md:'text/markdown',csv:'text/csv',html:'text/html',htm:'text/html',
    css:'text/css',js:'text/javascript',mjs:'text/javascript',json:'application/json',
    xml:'application/xml',yaml:'text/yaml',yml:'text/yaml',svg:'image/svg+xml',png:'image/png',
    jpg:'image/jpeg',jpeg:'image/jpeg',gif:'image/gif',webp:'image/webp',avif:'image/avif',
    ico:'image/x-icon',bmp:'image/bmp',pdf:'application/pdf',zip:'application/zip',
    gz:'application/gzip',wasm:'application/wasm',woff:'font/woff',woff2:'font/woff2',
    ttf:'font/ttf',otf:'font/otf',mp3:'audio/mpeg',wav:'audio/wav',ogg:'audio/ogg',
    mp4:'video/mp4',webm:'video/webm',bin:'application/octet-stream'};
  function guessMime(name){
    var m=String(name||'').toLowerCase().match(/\.([a-z0-9]+)$/);
    return (m&&MIME[m[1]])||'application/octet-stream';
  }
  // 对 SVG 等文本资源，百分号编码通常比 base64 更短
  function pctEncode(bytes){
    var s='';
    for(var i=0;i<bytes.length;i++){
      var c=bytes[i];
      var ch=String.fromCharCode(c);
      if(c>32&&c<127&&'#%<>?[\\]^`{|}"'.indexOf(ch)<0) s+=ch;
      else if(c===32) s+='%20';
      else s+='%'+('0'+c.toString(16).toUpperCase()).slice(-2);
    }
    return s;
  }
  function pctDecode(s){
    var o=[];
    for(var i=0;i<s.length;i++){
      if(s[i]==='%'&&i+2<s.length){ o.push(parseInt(s.substr(i+1,2),16)); i+=2; }
      else if(s[i]==='+') o.push(32);
      else o.push(s.charCodeAt(i));
    }
    return Uint8Array.from(o);
  }
  function encode(bytes,mime,opt){
    opt=opt||{};
    if(!bytes||typeof bytes.length!=='number') return {error:'请提供字节数组'};
    mime=mime||'application/octet-stream';
    var charset=opt.charset?(';charset='+opt.charset):'';
    var uri,mode;
    if(opt.mode==='pct'){ uri='data:'+mime+charset+','+pctEncode(bytes); mode='pct'; }
    else { uri='data:'+mime+charset+';base64,'+b64e(bytes); mode='base64'; }
    var over=bytes.length?((uri.length-bytes.length)/bytes.length*100):0;
    return {value:{uri:uri,mode:mode,raw:bytes.length,len:uri.length,
                   overhead:Math.round(over*10)/10,
                   css:'url("'+uri.replace(/"/g,'\\"')+'")'}};
  }
  function parse(uri){
    var s=String(uri||'').trim();
    if(s.slice(0,5).toLowerCase()!=='data:') return {error:'不是合法的 data: URI'};
    var comma=s.indexOf(',');
    if(comma<0) return {error:'缺少逗号分隔符'};
    var head=s.slice(5,comma),body=s.slice(comma+1);
    var segs=head.split(';'),mime=segs[0]||'text/plain',isB64=false,params={};
    for(var i=1;i<segs.length;i++){
      if(segs[i].toLowerCase()==='base64'){ isB64=true; continue; }
      var eq=segs[i].indexOf('=');
      if(eq>0) params[segs[i].slice(0,eq)]=segs[i].slice(eq+1);
    }
    var bytes=isB64?b64d(body):pctDecode(body);
    if(bytes===null) return {error:'base64 数据非法'};
    var isText=/^text\/|json|xml|javascript|svg|yaml/.test(mime);
    return {value:{mime:mime,base64:isB64,params:params,bytes:bytes,size:bytes.length,
                   text:isText?fromUtf8(bytes):null,isText:isText}};
  }
  function encodeText(text,mime,opt){ return encode(utf8(String(text)),mime||'text/plain',opt); }
  function fmtSize(n){
    if(n<1024) return n+' B';
    if(n<1048576) return (n/1024).toFixed(1)+' KB';
    return (n/1048576).toFixed(2)+' MB';
  }
  var API={encode:encode,parse:parse,encodeText:encodeText,guessMime:guessMime,
           b64e:b64e,b64d:b64d,utf8:utf8,fromUtf8:fromUtf8,pctEncode:pctEncode,
           pctDecode:pctDecode,fmtSize:fmtSize};
  if(typeof module!=='undefined'&&module.exports)module.exports=API;
  if(typeof window!=='undefined')window.__DataUriForge__=API;
})();
